import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        // Binary max-heap of capacities.
        long[] heap = new long[n];
        for (int i = 0; i < n; i++) heap[i] = nextLong();
        for (int i = n / 2 - 1; i >= 0; i--) siftDown(heap, n, i);
        long[] weights = new long[m];
        for (int i = 0; i < m; i++) weights[i] = nextLong();
        Arrays.sort(weights);
        // Heaviest package goes to the currently largest capacity, which then halves.
        for (int i = m - 1; i >= 0; i--) {
            if (heap[0] < weights[i]) {
                System.out.println(0);
                return;
            }
            heap[0] /= 2;
            siftDown(heap, n, 0);
        }
        System.out.println(1);
    }

    static void siftDown(long[] heap, int size, int i) {
        while (true) {
            int largest = i, l = 2 * i + 1, r = l + 1;
            if (l < size && heap[l] > heap[largest]) largest = l;
            if (r < size && heap[r] > heap[largest]) largest = r;
            if (largest == i) return;
            long t = heap[i];
            heap[i] = heap[largest];
            heap[largest] = t;
            i = largest;
        }
    }
}

package main

import (
	"container/heap"
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

// maxHeap is a max-heap of truck capacities.
type maxHeap []int

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	trucks := make(maxHeap, n)
	for i := range trucks {
		trucks[i] = nextInt()
	}
	heap.Init(&trucks)
	weights := make([]int, m)
	for i := range weights {
		weights[i] = nextInt()
	}
	sort.Sort(sort.Reverse(sort.IntSlice(weights)))
	// Heaviest package goes to the currently largest capacity, which then halves.
	for _, w := range weights {
		if trucks[0] < w {
			fmt.Println(0)
			return
		}
		trucks[0] /= 2
		heap.Fix(&trucks, 0)
	}
	fmt.Println(1)
}
